/**
 * Sit-to-Stand Biomechanics Lab - Configuration
 *
 * Every analysis parameter lives here and is documented in DATA_DICTIONARY.md
 * (generated by tools/build-dictionary.js). Defaults are engineering values chosen
 * from the biomechanics literature where one exists; items marked [TUNE] have NOT
 * been validated against a criterion measure and must be checked in a validation study.
 */
const CONFIG = {
    app: {
        name: 'Sit-to-Stand Biomechanics Lab',
        version: '1.0.0',
        analysisVersion: '1.0.0',
        schemaVersion: '1.0'
    },

    // Google Sheets (Apps Script web app). Leave empty to disable upload (local export only).
    sheets: {
        webhookUrl: '',
        uploadFrames: false   // true = also upload the analysed time series (~900 rows/test) to a "Frames" sheet
    },

    // MediaPipe Pose Landmarker
    pose: {
        defaultModel: 'full',
        numPoses: 1,
        detectionConfidence: 0.5,
        presenceConfidence: 0.5,
        trackingConfidence: 0.5,
        bundleUrl: 'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.18/vision_bundle.mjs',
        wasmUrl: 'https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.18/wasm',
        models: {
            lite:  'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_lite/float16/1/pose_landmarker_lite.task',
            full:  'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_full/float16/1/pose_landmarker_full.task',
            heavy: 'https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_heavy/float16/1/pose_landmarker_heavy.task'
        }
    },

    // Test protocol: CDC STEADI 30-Second Chair Stand (Jones, Rikli & Beam, 1999)
    protocol: {
        durationS: 30,
        countdownS: 3,
        preRollS: 1.0,          // seated frames kept before "Go" (filter warm-up, seated-at-start check)
        tailS: 2.0,             // frames kept after 30 s (lets the last rep finish; half-stand rule)
        chairHeightCm: 43.2,    // 17 in, STEADI standard
        halfwayProgress: 0.5    // CDC half-way rule
    },

    // Calibration (standing + seated, each captured while the participant is still)
    calibration: {
        holdS: 2.0,
        maxJitterTrunkFrac: 0.04,   // [TUNE] max SD of tracked markers during hold, as fraction of trunk length
        standMaxKneeFlexDeg: 25,    // must stand reasonably tall to calibrate
        standMaxTrunkInclDeg: 20,
        seatMinKneeFlexDeg: 55,
        heightRangeCm: [120, 210],
        hipRiseRangeM: [0.15, 0.65] // plausibility of seated->standing hip rise after scaling
    },

    // Whole-body anthropometry (Winter, 2009): trunk (shoulder-hip) 0.288H + thigh 0.245H + shank 0.246H
    anthropometry: { segmentChainFractionOfHeight: 0.779 },

    // Signal processing
    signal: {
        resampleHz: 30,
        cutoffHz: 6,            // effective -3 dB cutoff of the zero-lag (forward-backward) 2nd-order Butterworth
        maxGapS: 0.25,          // gaps longer than this are flagged (still bridged linearly for filtering)
        minVisibility: 0.5,     // MediaPipe visibility below this = marker treated as missing
        padSamples: 30
    },

    // Repetition event detection on hip-height progress p(t): 0 = seated baseline, 1 = calibrated standing
    events: {
        stateHi: 0.6,           // p rising through this = a stand attempt begins (state machine)
        stateLo: 0.4,           // p falling through this = seated again
        lowPct: 0.10,           // movement onset / seat contact level, % of local excursion
        highPct: 0.90,          // "standing reached" / "descent begins" level, % of local excursion
        fullStandProgress: 0.85,    // [TUNE] min peak progress to count as full stand (hip)
        kneeExtToleranceDeg: 20     // [TUNE] knee flexion at stand must be <= calibrated standing + this
    },

    // Arm use (CDC: arms must stay crossed; pushing off = test invalid)
    arms: {
        deviationThreshold: 0.35,   // [TUNE] wrist-to-shoulder-midpoint distance (trunk lengths) above seated-calibration value
        minDurationS: 0.2
    },

    // Quality control thresholds
    qc: {
        minEffectiveFps: 15,
        minValidFramePct: 90,
        maxImputedPct: 10,
        maxObliquity: 0.2,          // [TUNE] |L hip x - R hip x| / trunk length; ~0 side-on, ~0.4 frontal (hip width / trunk length); 0.2 ~ 30 deg off perpendicular
        maxScaleDiffPct: 10,
        maxAnkleShiftShankFrac: 0.15,
        maxShankVerticalDeg: 5,
        maxKnee2D3DDiffDeg: 10,
        blocking: ['LOW_FPS', 'LOW_VALID_FRAMES', 'TRACKING_GAPS', 'CAMERA_OR_FEET_SHIFT', 'NOT_SEATED_AT_START',
                   'MOVED_BEFORE_GO', 'ARM_USE_SUSPECTED', 'MANUAL_STOP', 'HIP_RISE_IMPLAUSIBLE', 'FACING_AMBIGUOUS']
    },

    // Live (causal) counter shown during the test; the offline analysis is authoritative
    live: { emaAlpha: 0.4, standAt: 0.85, seatAt: 0.25 },

    // MediaPipe landmarks recorded (index in the 33-point model). Order defines array layout.
    tracked: [
        { idx: 0,  key: 'nose',    name: 'nose',             role: 'Frame-fit check (head inside frame).' },
        { idx: 11, key: 'l_sh',    name: 'left_shoulder',    role: 'Trunk segment top; arm-position reference; obliquity.' },
        { idx: 12, key: 'r_sh',    name: 'right_shoulder',   role: 'Trunk segment top; arm-position reference; obliquity.' },
        { idx: 13, key: 'l_el',    name: 'left_elbow',       role: 'Recorded for reference (not used in metrics).' },
        { idx: 14, key: 'r_el',    name: 'right_elbow',      role: 'Recorded for reference (not used in metrics).' },
        { idx: 15, key: 'l_wr',    name: 'left_wrist',       role: 'Arm-use detection (wrist distance from chest).' },
        { idx: 16, key: 'r_wr',    name: 'right_wrist',      role: 'Arm-use detection (wrist distance from chest).' },
        { idx: 23, key: 'l_hip',   name: 'left_hip',         role: 'Pelvis proxy: vertical displacement, progress p(t), trunk & thigh angles.' },
        { idx: 24, key: 'r_hip',   name: 'right_hip',        role: 'Pelvis proxy; camera-obliquity estimate.' },
        { idx: 25, key: 'l_kn',    name: 'left_knee',        role: 'Knee angle, shank inclination.' },
        { idx: 26, key: 'r_kn',    name: 'right_knee',       role: 'Knee angle, shank inclination.' },
        { idx: 27, key: 'l_an',    name: 'left_ankle',       role: 'Knee angle, shank inclination, feet-stay-put check.' },
        { idx: 28, key: 'r_an',    name: 'right_ankle',      role: 'Knee angle, shank inclination, feet-stay-put check.' },
        { idx: 29, key: 'l_heel',  name: 'left_heel',        role: 'Foot direction (facing check).' },
        { idx: 30, key: 'r_heel',  name: 'right_heel',       role: 'Foot direction (facing check).' },
        { idx: 31, key: 'l_toe',   name: 'left_foot_index',  role: 'Ankle angle; foot direction.' },
        { idx: 32, key: 'r_toe',   name: 'right_foot_index', role: 'Ankle angle; foot direction.' }
    ],

    // CDC STEADI "Chair Stand - Below Average Scores" (2017). Below average = fewer stands than the value.
    steadi: {
        reference: 'CDC STEADI 30-Second Chair Stand (2017) below-average cut-points',
        male:   [[60, 64, 14], [65, 69, 12], [70, 74, 12], [75, 79, 11], [80, 84, 10], [85, 89, 8], [90, 94, 7]],
        female: [[60, 64, 12], [65, 69, 11], [70, 74, 10], [75, 79, 10], [80, 84, 9],  [85, 89, 8], [90, 94, 4]]
    },

    sounds: { enabled: true }
};

if (typeof module !== 'undefined') module.exports = CONFIG;
